const LANGS = { en, fr, zh, hi, fa }
const pack = (lang) => LANGS[lang] || en
function t(lang, key, ...args) {
  const p = pack(lang)
  if (key.startsWith('st_')) { const k = key.slice(3); return p.st?.[k] || en.st[k] || k }
  const v = p[key] ?? en[key]
  if (v == null) return key
  return typeof v === 'function' ? v(...args) : v
}
const btn = (lang) => ({ ...en.btn, ...pack(lang).btn })
const allLabels = (k) => Object.values(LANGS).map(l => l.btn[k])

module.exports = { t, btn, allLabels, LANGS }
